ALTER TABLE "site_settings" ADD COLUMN "about_page" jsonb DEFAULT '{"heroText":"Your trusted partner for quality packaging solutions, serving New York, New Jersey, and all of North America since 2010.","storyTitle":"Our Story","storyContent":"DreamPack has been a leading supplier of quality packaging products for over a decade. What started as a small family business has grown into a trusted partner for businesses across North America.\n\nWe take pride in offering a wide range of packaging solutions, from eco-friendly paper bags to elegant gift boxes. Our commitment to quality, competitive pricing, and exceptional customer service has made us the go-to choice for businesses of all sizes.","values":[{"title":"Quality Products","description":"We source and provide only the highest quality packaging materials to ensure your products are presented at their best.","icon":"shield"},{"title":"Competitive Pricing","description":"As a wholesale supplier, we offer competitive bulk pricing without compromising on quality.","icon":"dollar"},{"title":"Customer Service","description":"Our dedicated team is always ready to help you find the perfect packaging solution for your needs.","icon":"users"},{"title":"Fast Delivery","description":"We maintain extensive inventory to ensure quick turnaround times for your orders.","icon":"truck"}],"offerings":["Paper Bags & Shopping Bags","Food Packaging & Containers","Gift Boxes & Tissue Paper","Poly Bags & Plastic Packaging","Custom Printing Services","Eco-Friendly Options"],"ctaTitle":"Ready to Get Started?","ctaText":"Contact us today for a quote on your packaging needs."}'::jsonb;